set -e
cd "$(dirname "$0")"
openssl req -x509 -newkey rsa:2048 -nodes -keyout proxy.key -out proxy.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"
openssl req -x509 -newkey rsa:2048 -nodes -keyout origin.key -out origin.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"
surl --directory site http://127.0.0.1:8080/ https://127.0.0.1:8081/ --cert origin.pem --key origin.key &
surl --proxy https://127.0.0.1:8082/ --cert proxy.pem --key proxy.key -v --log-file proxy.log &
sleep 1
curl -sS --proxy-cacert proxy.pem -x https://127.0.0.1:8082/ http://127.0.0.1:8080/hello.txt
kill $(jobs -p)
